/**
 * Garment blanks for the sample maker.
 *
 * These are NOT drawn by hand. Every path here is extracted from a real
 * Adobe Illustrator tech pack with `tools/pdf-to-flat.py`, which walks the
 * PDF content stream and converts its path operators to SVG. Earlier versions
 * were drawn by eye and the proportions were consistently wrong — a t-shirt
 * came out as wide as it was tall.
 *
 * Each flat is the FRONT view only, isolated from the front/back sheet by
 * clustering paths on centre-x, then scaled so every garment is 600 units
 * tall. Height is the stable dimension: sleeve spread makes overall width vary
 * enormously between garments, so `cmPerUnit` is derived from a real body
 * length rather than a width.
 *
 *   silhouette  the outer shape — filled with the colourway, stroked
 *   detail      seams, hems, ribbing, plackets, pockets — stroked only
 *
 * Annotation is stripped during extraction: measurement rulers, spec boxes,
 * leader lines, and the tech pack's own chest logo (which would otherwise sit
 * exactly where the customer's artwork goes).
 *
 * `printArea` and `placements` are set by hand against the render — deriving
 * them geometrically kept failing on garments whose sleeves reach the hem.
 */

export type Placement = {
  id: string
  label: string
  /** Top-left of the artwork box, in viewBox units. */
  x: number
  y: number
  /** Artwork width in viewBox units. */
  w: number
}

export type Garment = {
  id: string
  name: string
  category: string
  viewBox: string
  /** Outer shape — used for the crisp outline stroke. */
  silhouette: string
  /**
   * The subset of paths large enough to be outline pieces (body, sleeve, leg,
   * hood). Filled together under nonzero to make the solid garment. Filling
   * only closed paths leaves shirts unfilled; filling every path closes the
   * detail lines into stray triangles.
   */
  fill: string[]
  /** Construction lines: stroked, never filled. */
  detail: string[]
  /** Region artwork is expected to sit within; drawn as a dashed guide. */
  printArea: { x: number; y: number; w: number; h: number }
  cmPerUnit: number
  placements: Placement[]
  /**
   * Optional licensed photographic mockup — see public/mockups/README.md.
   * When set it replaces the vector flat and the geometry above is read in the
   * image's own pixel space.
   */
  mockup?: { src: string; w: number; h: number }
}

